  "Settings.GraphicsQuality.Overall": "Overall Quality",
  "Settings.GraphicsQuality.Custom": "Custom",
  "Settings.GraphicsQuality.Texture": "Texture",
  "Settings.GraphicsQuality.Shadow": "Shadow",
  "Settings.GraphicsQuality.Effects": "Effects",
  "Settings.GraphicsQuality.Foliage": "Foliage",
  "Settings.GraphicsQuality.Shading": "Shading",
  "Settings.GraphicsQuality.ViewDistance": "View Distance",
  "Settings.Tooltip.Resolution.Body": "Sets the display resolution used by exclusive fullscreen mode. Borderless uses the desktop resolution instead.",
  "Settings.Tooltip.WindowMode.Body": "<bullet>Fullscreen - Exclusive display mode. Use it if you want the game to control resolution directly.</><bullet>Borderless - Fills the screen in a window. Alt-tab is smoother and the desktop resolution is used.</><bullet>Windowed - Runs inside a movable desktop window.</>",
  "Settings.Tooltip.VSync.Body": "Matches frame delivery to your monitor refresh to reduce tearing. It can add a small amount of input delay.",
  "Settings.Tooltip.FrameRateLimit.Body": "Caps the maximum frame rate. Lower caps reduce heat and power use. Unlimited lets the game render as fast as it can.",
  "Settings.Tooltip.ResolutionScale.Body": "Renders the 3D scene below or above the selected resolution. Lower values improve performance. Higher values sharpen the image but cost more GPU time. DLSS replaces this while enabled.",
  "Settings.Tooltip.DLSS.Body": "<bullet>Off - Uses normal rendering and the Resolution Scale slider.</><bullet>DLAA - Deep Learning Anti-Aliasing. It keeps native resolution and uses NVIDIA's neural anti-aliasing for a cleaner image.</><bullet>Quality - Upscales from a high internal resolution. This is the sharpest DLSS performance mode.</><bullet>Balanced - Trades some sharpness for more performance.</><bullet>Performance - Uses a lower internal resolution for a larger speed gain.</><bullet>Ultra Perf. - For very high display resolutions when frame rate matters more than detail.</>",
  "Settings.Tooltip.AntiAliasing.Body": "<bullet>None - Leaves hard pixel edges untouched.</><bullet>FXAA - Fast Approximate Anti-Aliasing. It is cheap but can soften the image.</><bullet>TAA - Temporal Anti-Aliasing. It blends frames over time for smoother edges and usually looks cleaner in motion.</>",
  "Settings.Tooltip.Gamma.Body": "Adjusts the mid-tones without moving pure black or pure white as much. Use it if the image looks washed out or too dark overall.",
  "Settings.Tooltip.Brightness.Body": "Shifts the whole image brighter or darker. Use it for display calibration after gamma feels right.",
  "Settings.Tooltip.OverallQuality.Body": "<bullet>Low - Prioritises speed.</><bullet>Medium - Balanced defaults for older or mid-range hardware.</><bullet>High - Strong image quality with higher GPU cost.</><bullet>Ultra - Maximum quality settings.</><bullet>Custom - Individual quality settings no longer match the same preset.</>",
  "Settings.Tooltip.TextureQuality.Body": "Controls texture resolution. Higher settings keep surfaces and UI-adjacent world details sharper but use more video memory.",
  "Settings.Tooltip.ShadowQuality.Body": "Controls shadow resolution and distance. Higher settings make shadows sharper and more stable at a higher GPU cost.",
  "Settings.Tooltip.EffectsQuality.Body": "Controls particles and visual effects. Higher settings add denser effects during weather and battles.",
  "Settings.Tooltip.FoliageQuality.Body": "Controls vegetation density and distance. Higher settings make the map look fuller but cost more GPU time.",
  "Settings.Tooltip.ShadingQuality.Body": "Controls material and lighting detail. Higher settings improve surface depth and lighting richness.",
  "Settings.Tooltip.ViewDistanceQuality.Body": "Controls how far detailed objects and terrain features stay visible. Higher settings reduce pop-in at a performance cost.",
  "Settings.Tooltip.ProvinceBorders.Body": "Shows political borders on the campaign map. Turn it off for a cleaner map view.",
  "Settings.Tooltip.FpsCounter.Body": "Shows the current frame rate while playing.",
  "Settings.Tooltip.GlanceDensity.Body": "<bullet>Minimal - Keeps only the most important map labels visible.</><bullet>Normal - Shows the usual campaign labels.</><bullet>Detailed - Keeps more labels visible while zoomed out.</>",
  "Settings.Tooltip.SettlementGlances.Body": "Shows settlement and port labels over the campaign map.",
  "Settings.Tooltip.MilitaryGlances.Body": "Shows army and navy labels over the campaign map.",
  "Settings.Tooltip.ConvoyGlances.Body": "Shows convoy labels while resource map mode is active.",
