  "TechnologyMock.Tech.ArchiveLedgers": "Archive Ledgers",
  "TechnologyMock.Tech.ArchiveLedgersSummary": "Standard records for tax and orders.",
  "TechnologyMock.Tech.ArchiveLedgersDetail": "Scribes keep matching ledgers for land, grain, soldiers, and coin so new orders start from shared numbers.",
  "TechnologyMock.Tech.ArchiveLedgersEffect": "Administrative actions cost 5% less knowledge.",
  "TechnologyMock.Tech.TaxRegisters": "Tax Registers",
  "TechnologyMock.Tech.TaxRegistersSummary": "Sharper accounts across loyal regions.",
  "TechnologyMock.Tech.TaxRegistersDetail": "Survey teams reconcile estate rolls with local stores, cutting the gaps that let money vanish before it reaches the treasury.",
  "TechnologyMock.Tech.TaxRegistersEffect": "Direct tax income +8%.",
  "TechnologyMock.Tech.CourierRelays": "Courier Relays",
  "TechnologyMock.Tech.CourierRelaysSummary": "Orders travel through staffed stations.",
  "TechnologyMock.Tech.CourierRelaysDetail": "Relay houses carry sealed orders between regional capitals, field armies, and court offices without waiting for ad hoc messengers.",
  "TechnologyMock.Tech.CourierRelaysEffect": "Governor order delay -20%.",
  "TechnologyMock.Tech.ProvincialCourts": "Provincial Courts",
  "TechnologyMock.Tech.ProvincialCourtsSummary": "Local disputes resolved before revolt.",
  "TechnologyMock.Tech.ProvincialCourtsDetail": "Trusted judges hear tax, land, and oath disputes before local patrons can turn them into open defiance.",
  "TechnologyMock.Tech.ProvincialCourtsEffect": "Unrest from corruption -10%.",
  "TechnologyMock.Tech.MusterRolls": "Muster Rolls",
  "TechnologyMock.Tech.MusterRollsSummary": "Every company counted and paid.",
  "TechnologyMock.Tech.MusterRollsDetail": "Commanders submit regular counts of soldiers, animals, and equipment so missing troops stop draining the treasury.",
  "TechnologyMock.Tech.MusterRollsEffect": "Army upkeep -4%.",
  "TechnologyMock.Tech.ShieldDrill": "Shield Drill",
  "TechnologyMock.Tech.ShieldDrillSummary": "Infantry hold under pressure.",
  "TechnologyMock.Tech.ShieldDrillDetail": "Veteran instructors teach close-order defence to frontier levies and court troops alike.",
  "TechnologyMock.Tech.ShieldDrillEffect": "Infantry morale +6%.",
  "TechnologyMock.Tech.SiegeSupply": "Siege Supply",
  "TechnologyMock.Tech.SiegeSupplySummary": "Campaign stores follow the army.",
  "TechnologyMock.Tech.SiegeSupplyDetail": "Pack depots and requisition tables keep pressure on walls without starving the besieging army first.",
  "TechnologyMock.Tech.SiegeSupplyEffect": "Siege attrition -12%.",
  "TechnologyMock.Tech.FieldStandards": "Field Standards",
  "TechnologyMock.Tech.FieldStandardsSummary": "Commands stay clear in broken battles.",
  "TechnologyMock.Tech.FieldStandardsDetail": "Shared standards, signals, and command rituals keep mixed armies responsive when allied contingents arrive late.",
  "TechnologyMock.Tech.FieldStandardsEffect": "Army cohesion +10%.",
  "TechnologyMock.Tech.StoneSurvey": "Stone Survey",
  "TechnologyMock.Tech.StoneSurveySummary": "Builders know what can be raised.",
  "TechnologyMock.Tech.StoneSurveyDetail": "Inspectors record quarry access, road distance, and skilled labour before costly public works begin.",
  "TechnologyMock.Tech.StoneSurveyEffect": "Building planning cost -6%.",
  "TechnologyMock.Tech.RoadCrews": "Road Crews",
  "TechnologyMock.Tech.RoadCrewsSummary": "Repair teams keep routes usable.",
  "TechnologyMock.Tech.RoadCrewsDetail": "Permanent crews patch bridges, clear slides, and mark safe staging grounds for officials and supply wagons.",
  "TechnologyMock.Tech.RoadCrewsEffect": "Land convoy speed +15%.",
  "TechnologyMock.Tech.FortifiedStorehouses": "Fortified Storehouses",
  "TechnologyMock.Tech.FortifiedStorehousesSummary": "Food and arms survive raids.",
  "TechnologyMock.Tech.FortifiedStorehousesDetail": "Regional depots move grain, tools, and armour behind guarded walls before raiders or rebels can seize them.",
  "TechnologyMock.Tech.FortifiedStorehousesEffect": "Settlement stockpile loss -18%.",
  "TechnologyMock.Tech.HarbourSurveys": "Harbour Surveys",
  "TechnologyMock.Tech.HarbourSurveysSummary": "Ports report capacity before fleets arrive.",
  "TechnologyMock.Tech.HarbourSurveysDetail": "Harbour masters record berths, pilots, and warehouses so naval supply plans stop guessing at coastal capacity.",
  "TechnologyMock.Tech.HarbourSurveysEffect": "Port trade value +10%.",
  "TechnologyMock.Tech.OathCouncils": "Oath Councils",
  "TechnologyMock.Tech.OathCouncilsSummary": "Local leaders renew public loyalty.",
  "TechnologyMock.Tech.OathCouncilsDetail": "Assemblies bind governors, commanders, guild heads, and clergy to public promises that players can later enforce.",
  "TechnologyMock.Tech.OathCouncilsEffect": "Subject loyalty drift +5%.",
  "TechnologyMock.Tech.PublicGranaries": "Public Granaries",
  "TechnologyMock.Tech.PublicGranariesSummary": "Food relief becomes predictable.",
  "TechnologyMock.Tech.PublicGranariesDetail": "Public stores release measured grain before panic spreads, making shortages a managed crisis instead of a spark.",
  "TechnologyMock.Tech.PublicGranariesEffect": "Shortage unrest -15%.",
  "TechnologyMock.Tech.TempleAccounts": "Temple Accounts",
  "TechnologyMock.Tech.TempleAccountsSummary": "Sacred estates join the ledger.",
  "TechnologyMock.Tech.TempleAccountsDetail": "Temple treasurers and court scribes share audited accounts without stripping local shrines of authority.",
